'use client';
import React, { useEffect } from 'react';

interface PortfolioProps {
  onOpenModal?: (title: string, desc: string) => void;
}

export default function Portfolio({ onOpenModal }: PortfolioProps) {

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        }
      });
    }, { threshold: 0.1 });

    const elements = document.querySelectorAll('.fu');
    elements.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  const openModal = (title: string, desc: string) => {
     if (onOpenModal) onOpenModal(title, desc);
     else console.log("Open modal:", title, desc);
  };

  const toggleFaq = (el: HTMLElement) => {
    const body = el.nextElementSibling as HTMLElement;
    if (el.classList.contains('active')) {
      el.classList.remove('active');
      body.style.maxHeight = '0';
    } else {
      el.classList.add('active');
      body.style.maxHeight = body.scrollHeight + 'px';
    }
  };

  return (
    <section id="work">
  <div className="work-head">
    <div>
      <div className="eyebrow">Portfolio</div>
      <h2 className="sec-title">Our <em>Work</em></h2>
      <p className="sec-body" style={{maxWidth: '420px'}}>Our work transforms the night sky into a canvas of storytelling, where technology meets creativity.</p>
    </div>
    <a href="#contact" className="btn-o">Commission a Show →</a>
  </div>
  <div className="work-masonry fu">
    <div className="work-item large" onClick={() => openModal(`Gujarat Police`, `FLYBIT displayed the Gujarat Police emblem in the sky — a landmark show representing trust, government partnership, and precision at scale.`)}>
      <img src="data:image/jpeg;base64," alt="Gujarat Police" />
      <div className="work-overlay"><span className="work-label">Gujarat Police · Government</span></div>
    </div>
    <div className="work-item" onClick={() => openModal(`Wedding Heart · Ahmedabad`, `A heart formation with the couple standing below — a wedding finale that left the entire crowd speechless. One of FLYBIT's most emotional shows.`)}>
      <img src="data:image/jpeg;base64," alt="Heart formation" />
      <div className="work-overlay"><span className="work-label">Wedding Heart Formation</span></div>
    </div>
    <div className="work-item" onClick={() => openModal(`ISRO Formation`, `A tribute to India's space achievements — ISRO's logo written in the sky above Science City, Ahmedabad. Client: Science City Ahmedabad.`)}>
      <img src="data:image/jpeg;base64," alt="ISRO" />
      <div className="work-overlay"><span className="work-label">ISRO · Science City</span></div>
    </div>
    <div className="work-item" onClick={() => openModal(`Portrait Formation`, `A stunning human portrait/silhouette formation — FLYBIT's most technically demanding category, requiring precise multi-drone depth mapping.`)}>
      <img src="data:image/jpeg;base64," alt="Person silhouette" />
      <div className="work-overlay"><span className="work-label">Portrait Silhouette</span></div>
    </div>
    <div className="work-item" onClick={() => openModal(`National India Map`, `India's tricolour map — orange, blue, green — one of our most iconic patriotic shows. Performed for national celebrations and tourism events.`)}>
      <img src="data:image/jpeg;base64," alt="India map formation" />
      <div className="work-overlay"><span className="work-label">India Map · National Event</span></div>
    </div>
  </div>
</section>
  );
}
